CREATE TABLE IF NOT EXISTS legacy_project_billing_classifications (project_id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT, legacy_billing_type text NOT NULL, target_billing_model text, confidence text NOT NULL DEFAULT 'unreviewed', evidence jsonb NOT NULL DEFAULT '{}'::jsonb, reviewed_by text REFERENCES users(id) ON DELETE SET NULL, reviewed_at timestamptz, notes text, FOREIGN KEY(project_id,workspace_id) REFERENCES projects(id,workspace_id) ON DELETE RESTRICT, CHECK(target_billing_model IS NULL OR target_billing_model IN ('fixed_price','retainer')), CHECK(confidence IN ('unreviewed','automatic','manual','blocked')));
